import { Component, OnInit } from '@angular/core';
import { GovBrSelectModule, GovBrTabModule } from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { SimuladorBaseCalculoCbsIbsMercadoriasComponent } from './simulador-base-calculo-cbs-ibs-mercadorias/simulador-base-calculo-cbs-ibs-mercadorias.component';
import { Subscription } from 'rxjs';
import { DispositivoService } from '../../services/dispositivo.service';
import { MyTitleComponent } from '../diversos/my-title/my-title.component';
import { SimuladorBaseCalculoIsMercadoriasComponent } from './simulador-base-calculo-is-mercadorias/simulador-base-calculo-is-mercadorias.component';

@Component({
    selector: 'simulador-base-calculo',
    templateUrl: './simulador-base-calculo.component.html',
    styleUrl: './simulador-base-calculo.component.scss',
    standalone: true,
    imports: [
        CommonModule,
        ReactiveFormsModule,
        GovBrSelectModule,
        GovBrTabModule,
        SimuladorBaseCalculoCbsIbsMercadoriasComponent,
        SimuladorBaseCalculoIsMercadoriasComponent,
        MyTitleComponent
    ],
    providers: [],
})
export class SimuladorBaseCalculoComponent implements OnInit {

    private subscriptions: Subscription = new Subscription();
    dispositivo: string = '';
    opcao: number = 1;

    form!: FormGroup;
    opcaoValues: any[] = [];

    constructor(
        private formBuilder: FormBuilder,
        private dispositivoService: DispositivoService,
    ) { }

    ngOnInit(): void {
        this.opcaoValues = [
            { id: 1, label: 'CBS e IBS para mercadorias' },
            // { id: 2, label: 'CBS e IBS para serviços' },
            { id: 3, label: 'IS para mercadorias' },
        ];
        this.form = this.formBuilder.group({
            opcaoControl: [{ value: this.opcaoValues[0], disabled: false }, []],
        });
        this.setSubscriptions();
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    opcaoControlChange(event: any) {
        this.opcao = event.id;
    }

    setSubscriptions() {
        this.subscriptions.add(
            this.dispositivoService.dispositivo$.subscribe((dispositivo) => { 
                this.dispositivo = dispositivo;
            })
        );
        this.subscriptions.add(
            this.form.get('opcaoControl')?.valueChanges.subscribe(value => {
                this.opcaoControlChange(value);
            })
        );
    }

}
