import { Component, OnInit, OnDestroy } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { GovBrInputModule } from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { BaseDeCalculoService } from '../../../services/base-de-calculo.service';
import { BarraBotoesComponent } from '../../diversos/barra-botoes/barra-botoes.component';
import { MensagemService } from '../../../services/mensagem.service';

@Component({
  selector: 'simulador-base-calculo-cbs-ibs-mercadorias',
  templateUrl: './simulador-base-calculo-cbs-ibs-mercadorias.component.html',
  styleUrl: './simulador-base-calculo-cbs-ibs-mercadorias.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrInputModule,
    BarraBotoesComponent
  ]
})
export class SimuladorBaseCalculoCbsIbsMercadoriasComponent implements OnInit, OnDestroy {

  public form!: FormGroup;

  response: any = null;

  constructor(
    private readonly baseDeCalculoService: BaseDeCalculoService,
    private readonly formBuilder: FormBuilder,
    private mensagemService: MensagemService
  ) { }


  ngOnDestroy(): void {

  }

  ngOnInit(): void {

    this.form = this.formBuilder.group({

      valorFornecimentoControl: [105.00, [Validators.required]],
      ajusteValorOperacaoControl: [5.00, [Validators.required]],
      jurosControl: [5.00, [Validators.required]],
      multasControl: [5.00, [Validators.required]],
      acrescimosControl: [5.00, [Validators.required]],
      encargosControl: [5.00, [Validators.required]],
      descontosCondicionaisControl: [5.00, [Validators.required]],
      fretePorDentroControl: [5.00, [Validators.required]],
      outrosTributosControl: [5.00, [Validators.required]],
      impostoSeletivoControl: [5.00, [Validators.required]],
      demaisImportanciasControl: [5.00, [Validators.required]],

      icmsControl: [5.00, [Validators.required]],
      issControl: [5.00, [Validators.required]],
      pisControl: [5.00, [Validators.required]],
      cofinsControl: [5.00, [Validators.required]],

      valorBaseCalculoControl: [0, [Validators.required]],
    });

    this.form.valueChanges.subscribe((value) => {
      this.resetarValores();
    });

  }

  resetarValores() {
    this.response = null;
  }

  limpar = () => {
    this.form.reset();
    this.resetarValores();
  }

  submit(event: any) {

    if (!this.form.valid) {
      this.mensagemService.mostrar('Erro', 'Erro', 'Formulário inválido.');
      return;
    }

    const body = {
      valorFornecimento: this.form.controls["valorFornecimentoControl"].value,
      ajusteValorOperacao: this.form.controls["ajusteValorOperacaoControl"].value,
      juros: this.form.controls["jurosControl"].value,
      multas: this.form.controls["multasControl"].value,
      acrescimos: this.form.controls["acrescimosControl"].value,
      encargos: this.form.controls["encargosControl"].value,
      descontosCondicionais: this.form.controls["descontosCondicionaisControl"].value,
      fretePorDentro: this.form.controls["fretePorDentroControl"].value,
      outrosTributos: this.form.controls["outrosTributosControl"].value,
      impostoSeletivo: this.form.controls["impostoSeletivoControl"].value,
      demaisImportancias: this.form.controls["demaisImportanciasControl"].value,
      icms: this.form.controls["icmsControl"].value,
      iss: this.form.controls["issControl"].value,
      pis: this.form.controls["pisControl"].value,
      cofins: this.form.controls["cofinsControl"].value,
    }

    this.baseDeCalculoService.aferirBaseDeCalculoCIBS(body).subscribe({
      next: data => {
        this.response = data;
      },
      error: error => {

      }
    });

  }

  controlChange(event: any) {

  }

}
